function checkFence(record) {
 if(record.text===undefined) return {id:record.id,returned_text_block:false};
 const runs=record.text.match(/`+/g)||[];
 const L=runs.reduce((max,run)=>Math.max(max,run.length),0);
 const K=Math.max(3,L+1);
 return {id:record.id,returned_text_block:true,longest_backtick_run:L,fence_length:K,marker:"`".repeat(K)};
}
const results=records.map(checkFence);

function fullSource(request) {
 return request.includes("Source:\n")?request.split("Source:\n")[1]:request.split(": ").slice(1).join(": ");
}
function finalCheck(record,request,response,fence) {
 const result={id:record.id};
 if(record.text!==undefined) {
  const prefix=fence.marker+"text\n";
  const suffix="\n"+fence.marker;
  const expected=prefix+record.text+suffix;
  result.block_equals_complete_final_text=response.response.startsWith(expected);
  result.longest_backtick_run=(record.text.match(/`+/g)||[]).reduce((n,s)=>Math.max(n,s.length),0);
  result.matching_safe_fences=fence.fence_length>result.longest_backtick_run&&response.response.startsWith(prefix)&&response.response.slice(prefix.length+record.text.length).startsWith(suffix);
 }
 const shortened=new Set(["trim-the-fat","less-wordy","more-concise","more-succinct","shorten-markdown-changes-quotes"]);
 if(shortened.has(record.id)) {
  const count=s=>s.trim().split(/\s+/u).filter(unit=>unit&&!/^(?:`+|~+|\*+|_+|-+|\|)$/u.test(unit)).length;
  const N=count(fullSource(request)),M=count(record.text);
  result.original_words=N;result.final_words=M;result.reduction=(N-M)/N;result.reduction_percent=100*(N-M)/N;
  result.convention="whitespace-separated units excluding standalone fence/markup delimiters";
 }
 return result;
}
const checks=records.map((r,i)=>finalCheck(r,requests[r.id],responses[i],fences[r.id]));

function escapeQuote(text) {
 return '**"'+[...text].map(ch=>{
  const n=ch.codePointAt(0);
  return ((n>=33&&n<=47)||(n>=58&&n<=64)||(n>=91&&n<=96)||(n>=123&&n<=126))?"\\"+ch:ch;
 }).join("")+'"**';
}
function fullSource(request) {
 return request.includes("Source:\n")?request.split("Source:\n")[1]:request.split(": ").slice(1).join(": ");
}
function makeResponse(record,request,fence) {
 if(record.direct!==undefined) return {id:record.id,response:record.direct};
 let response=fence.marker+"text\n"+record.text+"\n"+fence.marker;
 if(!record.draft) {
  const changes=record.full?[[fullSource(request),record.text,record.explanation]]:record.changes;
  response+="\n\nChanges:\n"+changes.map(([before,after,explanation])=>"- "+escapeQuote(before)+" → "+escapeQuote(after)+": "+explanation).join("\n");
 }
 return {id:record.id,response};
}
